function escapeHtml(e){return(e+"").replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/'/g,"&#39;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}function encodePath(e){return e.split("/").map(e=>encodeURIComponent(e).replace(/'/g,"%27")).join("/")}function formatPokemonSearch(e){return e.image?.length?$(`<span class='pokemonSearchOption'><img class='pokemonSearchIcon me-1' src='/includes/images/sprites/${encodePath(e.image)}' alt='${escapeHtml(e.alt)}' loading='lazy'>${e.text}</span>`):e.text}function formatFriendSearchResults(e){if(!e.loading)return $(`<span class='trainerSearchOption'><img class='searchIcon me-1' src='/includes/images/icons/${encodePath(e.img)}.webp' alt='${escapeHtml(e.alt)}' loading='lazy'>${e.text}</span>`)}function formatCustomSearchResults(e){if(!e.loading)return $(`<span>${e.text}</span>`)}function addFocusEvent(){$(".select2-container").on("click",()=>{$(".select2-search__field").focus()})}export function createPokemonSearch(e){const a=$("#"+e);a.select2({ajax:{url:"/pokemon/search",dataType:"json",data:e=>({search:e.term,page:e.page||1}),processResults:e=>e.data,cache:!0,delay:150},minimumInputLength:1,maximumInputLength:20,placeholder:"Search a Pokemon...",theme:"bootstrap-5",templateResult:formatPokemonSearch,width:"100%"}),a.on("select2:select",e=>{const a=e.params.data.ses;window.location.href="/pokemon/"+a}),addFocusEvent()}export function createAddFriendSearch(e){$("#"+e).select2({ajax:{url:"/friend/searchFriendsToAdd",dataType:"json",data:e=>({search:e.term,page:e.page||1}),processResults:e=>e.data,cache:!0,delay:250},placeholder:"Search a Trainer...",theme:"bootstrap-5",maximumInputLength:15,templateResult:formatFriendSearchResults,width:"100%",dropdownParent:$("#addFriendModal")}),addFocusEvent()}export function createFriendsListSearch(e){$("#"+e).select2({ajax:{url:"/friend/searchFriendsList",dataType:"json",data:e=>({search:e.term,page:e.page||1}),processResults:e=>e.data,cache:!0,delay:250},placeholder:"Select a Friend",theme:"bootstrap-5",maximumInputLength:15,templateResult:formatFriendSearchResults,width:"100%"}),addFocusEvent()}export function createCustomSearch(e,a="Select a Custom Pokedex",t=!1,o="100%"){const c=$("#"+e);c.select2({ajax:{url:"/pokedex/searchCustomPokedexList",dataType:"json",data:e=>({search:e.term,page:e.page||1}),processResults:e=>e.data,cache:!0,delay:250},placeholder:a,theme:"bootstrap-5",maximumInputLength:15,templateResult:formatCustomSearchResults,width:o}),addFocusEvent(),t&&c.on("select2:select",e=>{const a=e.params.data.id;window.location.href="/mycustompokedex/"+a})}export function createRegionSelect(e){$("#"+e).select2({minimumResultsForSearch:1/0,placeholder:"Select a Region",theme:"bootstrap-5",width:"100%"})}